public class Main {
    static { System.out.println("A"); }

    public static void main(String[] args) {
        System.out.println("B");
        for (int i = 0; i < 1_000_000; i++) work(i);
        System.out.println("C");
    }

    static int work(int i) { return i * 2; }
}

